import{_ as e,o as a,c as l,ag as r}from"./chunks/framework.qXLDknWC.js";const c=JSON.parse('{"title":"Sampler Settings","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/sampler-settings.md","filePath":"configuration/sampler-settings.md"}'),i={name:"configuration/sampler-settings.md"};function s(n,t,o,d,p,h){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="sampler-settings" tabindex="-1">Sampler Settings <a class="header-anchor" href="#sampler-settings" aria-label="Permalink to &quot;Sampler Settings&quot;">​</a></h1><p>Sampler settings control how the AI generates text — balancing creativity, coherence, and diversity. Character Vault exposes the most commonly used sampling parameters.</p><h2 id="accessing-sampler-settings" tabindex="-1">Accessing Sampler Settings <a class="header-anchor" href="#accessing-sampler-settings" aria-label="Permalink to &quot;Accessing Sampler Settings&quot;">​</a></h2><ol><li>Open a character in the workspace.</li><li>Click <strong>Settings</strong> in the workspace header.</li><li>Click the <strong>Sampler</strong> tab.</li></ol><h2 id="quick-presets" tabindex="-1">Quick Presets <a class="header-anchor" href="#quick-presets" aria-label="Permalink to &quot;Quick Presets&quot;">​</a></h2><p>Three built-in presets apply common parameter combinations with one click:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Preset</th><th style="text-align:left;">Temperature</th><th style="text-align:left;">Context</th><th style="text-align:left;">Max Tokens</th><th style="text-align:left;">Best For</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Creative</strong></td><td style="text-align:left;">0.9</td><td style="text-align:left;">4K</td><td style="text-align:left;">2048</td><td style="text-align:left;">Brainstorming, storytelling, expanding descriptions</td></tr><tr><td style="text-align:left;"><strong>Balanced</strong></td><td style="text-align:left;">0.7</td><td style="text-align:left;">4K</td><td style="text-align:left;">2048</td><td style="text-align:left;">General-purpose writing and editing</td></tr><tr><td style="text-align:left;"><strong>Factual</strong></td><td style="text-align:left;">0.3</td><td style="text-align:left;">4K</td><td style="text-align:left;">1024</td><td style="text-align:left;">Grammar fixes, factual rewrites, concise edits</td></tr></tbody></table><p>Select a preset to apply its values, then fine-tune individual parameters as needed.</p><h2 id="primary-samplers" tabindex="-1">Primary Samplers <a class="header-anchor" href="#primary-samplers" aria-label="Permalink to &quot;Primary Samplers&quot;">​</a></h2><p>These are the most commonly adjusted parameters:</p><h3 id="temperature" tabindex="-1">Temperature <a class="header-anchor" href="#temperature" aria-label="Permalink to &quot;Temperature&quot;">​</a></h3><p>Controls randomness in generation. Lower values produce more focused, deterministic output. Higher values produce more creative, varied output.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Behavior</th></tr></thead><tbody><tr><td style="text-align:left;">0.0</td><td style="text-align:left;">Fully deterministic (not recommended — can produce repetitive text)</td></tr><tr><td style="text-align:left;">0.3 – 0.5</td><td style="text-align:left;">Focused and consistent</td></tr><tr><td style="text-align:left;">0.7</td><td style="text-align:left;">Balanced (default)</td></tr><tr><td style="text-align:left;">0.9 – 1.0</td><td style="text-align:left;">Creative and varied</td></tr><tr><td style="text-align:left;">1.5 – 2.0</td><td style="text-align:left;">Highly unpredictable</td></tr></tbody></table><p><strong>Range</strong>: 0.0 – 2.0 (step: 0.1)</p><h3 id="top-p" tabindex="-1">Top P <a class="header-anchor" href="#top-p" aria-label="Permalink to &quot;Top P&quot;">​</a></h3><p>Nucleus sampling — considers only tokens whose cumulative probability is below the threshold. Lower values restrict output to more likely tokens.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Behavior</th></tr></thead><tbody><tr><td style="text-align:left;">0.5</td><td style="text-align:left;">Very focused — considers only the most likely tokens</td></tr><tr><td style="text-align:left;">0.95</td><td style="text-align:left;">Permissive (Creative preset default)</td></tr><tr><td style="text-align:left;">1.0</td><td style="text-align:left;">No filtering — all tokens considered (Balanced preset default)</td></tr></tbody></table><p><strong>Range</strong>: 0.0 – 1.0 (step: 0.05)</p><h3 id="min-p" tabindex="-1">Min P <a class="header-anchor" href="#min-p" aria-label="Permalink to &quot;Min P&quot;">​</a></h3><p>Minimum probability threshold. Filters out tokens with probabilities below this percentage of the top token&#39;s probability. Unlike Top P, this works relative to the best token, making it more adaptive at different probability scales.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Behavior</th></tr></thead><tbody><tr><td style="text-align:left;">0.0</td><td style="text-align:left;">No filtering</td></tr><tr><td style="text-align:left;">0.05</td><td style="text-align:left;">Light filtering (default)</td></tr><tr><td style="text-align:left;">0.1</td><td style="text-align:left;">Moderate filtering (Factual preset)</td></tr></tbody></table><p><strong>Range</strong>: 0.0 – 1.0 (step: 0.01)</p><h3 id="top-k" tabindex="-1">Top K <a class="header-anchor" href="#top-k" aria-label="Permalink to &quot;Top K&quot;">​</a></h3><p>Limits token selection to the K most likely candidates. Lower values restrict output more aggressively.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Behavior</th></tr></thead><tbody><tr><td style="text-align:left;">20</td><td style="text-align:left;">Very focused (Factual preset)</td></tr><tr><td style="text-align:left;">40</td><td style="text-align:left;">Moderate (Balanced preset default)</td></tr><tr><td style="text-align:left;">50</td><td style="text-align:left;">Permissive (Creative preset)</td></tr><tr><td style="text-align:left;">100</td><td style="text-align:left;">Very permissive — nearly all tokens considered</td></tr></tbody></table><p><strong>Range</strong>: 1 – 100 (step: 1)</p><h2 id="secondary-samplers" tabindex="-1">Secondary Samplers <a class="header-anchor" href="#secondary-samplers" aria-label="Permalink to &quot;Secondary Samplers&quot;">​</a></h2><h3 id="repetition-penalty" tabindex="-1">Repetition Penalty <a class="header-anchor" href="#repetition-penalty" aria-label="Permalink to &quot;Repetition Penalty&quot;">​</a></h3><p>Penalizes repeated tokens and phrases. Values above 1.0 discourage repetition; values at 1.0 disable the penalty.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Behavior</th></tr></thead><tbody><tr><td style="text-align:left;">1.0</td><td style="text-align:left;">No penalty</td></tr><tr><td style="text-align:left;">1.05</td><td style="text-align:left;">Light anti-repetition (Creative preset)</td></tr><tr><td style="text-align:left;">1.1</td><td style="text-align:left;">Moderate (Balanced preset default)</td></tr><tr><td style="text-align:left;">1.2</td><td style="text-align:left;">Strong (Factual preset)</td></tr><tr><td style="text-align:left;">1.5+</td><td style="text-align:left;">May produce awkward or stilted phrasing</td></tr></tbody></table><p><strong>Range</strong>: 1.0 – 2.0 (step: 0.05)</p><h3 id="max-tokens" tabindex="-1">Max Tokens <a class="header-anchor" href="#max-tokens" aria-label="Permalink to &quot;Max Tokens&quot;">​</a></h3><p>The maximum number of tokens the AI will generate in a single response.</p><ul><li>Lower values (100–500) produce concise replies.</li><li>Medium values (1024–2048) work well for most character content.</li><li>Higher values (4096–8192) allow detailed, long-form responses.</li></ul><p><strong>Range</strong>: 100 – 8,192 (step: 100)</p><h3 id="context-length" tabindex="-1">Context Length <a class="header-anchor" href="#context-length" aria-label="Permalink to &quot;Context Length&quot;">​</a></h3><p>The total token window for AI requests (input + output combined). This is selected from a dropdown with predefined sizes:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Option</th><th style="text-align:left;">Token Count</th></tr></thead><tbody><tr><td style="text-align:left;">2K</td><td style="text-align:left;">2,048</td></tr><tr><td style="text-align:left;">4K</td><td style="text-align:left;">4,096 (default)</td></tr><tr><td style="text-align:left;">8K</td><td style="text-align:left;">8,192</td></tr><tr><td style="text-align:left;">16K</td><td style="text-align:left;">16,384</td></tr><tr><td style="text-align:left;">32K</td><td style="text-align:left;">32,768</td></tr><tr><td style="text-align:left;">64K</td><td style="text-align:left;">65,536</td></tr><tr><td style="text-align:left;">128K</td><td style="text-align:left;">131,072</td></tr></tbody></table><p>Choose a context length that matches or is lower than the maximum supported by your selected model. Larger windows allow the AI to work with more text but cost more and take longer.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Max Tokens is capped at 8,192 on save. If you enter a value above this, it will be clamped down automatically.</p></div><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>For the AI assistant (Orion)</strong>: A balanced or creative preset works well for brainstorming character details.</li><li><strong>For the AI toolbar</strong>: Factual or balanced is often better for grammar fixes and rewrites; creative is better for vivid/emotion operations.</li><li><strong>High Temperature + Min P</strong>: Using Min P alongside a higher Temperature helps maintain coherence while allowing creative output.</li><li><strong>Repetition Penalty</strong>: Values above 1.2 can start to produce awkward phrasing. Use sparingly.</li><li><strong>Non-standard parameters</strong>: Some models don&#39;t support <code>min_p</code>, <code>top_k</code>, <code>repetition_penalty</code>, or reasoning parameters. If a model rejects these, Character Vault automatically strips them and retries the request (up to 3 attempts).</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/configuration/ai-setup">Configure your AI provider</a></li><li><a href="/CharacterVault/docs/features/ai-assistant">Use the AI assistant</a></li></ul>',44)])])}const f=e(i,[["render",s]]);export{c as __pageData,f as default};
